// Ported from Limbophobia src/content/items/_kit.ts (same author): its texture painters only; the geometry and game code stay there.
// Generated by the material library's extractor and then kept by hand. Paints at 32 px per metre (src/gfx/mat/atlas.ts).
import { addTextureModule } from '../../../textures/index';
import { atlas } from '../../../atlas';
import { PixelCanvas } from '../../../pixel';
import { Rng } from '../../../rng';

// ------------------------------------------------------------------ texture queue
type Draw = (pc: PixelCanvas, rng: Rng) => void;
interface QTex { name: string; w: number; h: number; draw: Draw; tile: boolean }
const QUEUE: QTex[] = [];
addTextureModule(() => {
  const A = atlas();
  for (const q of QUEUE) {
    A.add(q.name, q.w, q.h, (pc, rng) => {
      pc.wrap = q.tile;
      try { q.draw(pc, rng); } catch (e) { console.error('item texture failed', q.name, e); pc.fill(0xff00ff); }
    });
  }
});
